snips.mod_go:
// Module is one entry in the JSON-lines stream emitted by `go list -m -json`.
// Update and Replace are recursive (the newer version and the replacement of a
// module are each described by a full Module), mirroring the go-tool shape and
// keeping encoding/json diagnostics identical to the reference program for
// every malformed-field case.
type Module struct {
	Path      string
	Version   string
	Time      *time.Time
	Indirect  bool
	Update    *Module
	Error     *ModuleError
	Replace   *Module
	Dir       string
	Main      bool
	GoVersion string
	GoMod     string
}

